-- Officially sourced macro release backfill for the January-July 2026 archive.
-- Consensus forecasts are intentionally NULL: official agencies do not publish market consensus forecasts.
on conflict(event_id) do update set event_time=excluded.event_time,event_name=excluded.event_name,country_code=excluded.country_code,currency=excluded.currency,impact=excluded.impact,actual=excluded.actual,forecast=excluded.forecast,previous=excluded.previous,revised_previous=excluded.revised_previous,unit=excluded.unit,source=excluded.source,source_url=excluded.source_url,category=excluded.category,raw_event=excluded.raw_event,synced_at=now();